from ordering import ordered
def coalesce(intervals):
    items = ordered(intervals)
    result = []
    for start, end in items:
        if result and start <= result[-1][1]:
            result[-1] = (result[-1][0], max(result[-1][1], end))
        else:
            result.append((start, end))
    return result

